+using System;
+using System.Data;
+using System.Text;
+using System.Web;
+using System.Web.UI.WebControls;
+using SimsObject;
+using WebGlobal;
+namespace InformationWeb.Controls.Learning
+{
+    public partial class SubjectMarkDetail_V2 : ControlBase
+    {
+        #region Const
+        private const string PERMISSION_VIEW = "frmWebSubjectMarkDetail_View";
+        #endregion
+        #region Variables
+        private int? intRegulationIDCurrent = null;
+        private DataTable dtbData = null;
+        private DataTable dtbClassSubject = null;
+        private DataTable dtbSubjectMark = null;
+        private bool bolHaveNormalSubject = false;
+        #endregion
+        #region Support methods
+        private void LoadData()
+        {
+            SIM_SubjectMark objSubjectMark = new SIM_SubjectMark();
+            SIM_Class_Subject objClassSubject = new SIM_Class_Subject();
+            SIM_Student objStudent = new SIM_Student();
+            intRegulationIDCurrent = uClass.RegulationID;
+            string strListGraduationSpecialType = "," + Global.SubjectSpecialType.TotNghiepVanHoa.ToString()
+                                                + "," + Global.SubjectSpecialType.ChinhTriTotNghiep.ToString()
+                                                + "," + Global.SubjectSpecialType.TotNghiepLT.ToString()
+                                                + "," + Global.SubjectSpecialType.TotNghiepTH.ToString() + ",";
+            if (IsRegulation43OfClass())
+            {
+                int? intOrderLearning = null;
+                if (chkViewOnlyExam1.Checked)
+                    intOrderLearning = 1;
+                dtbSubjectMark = objSubjectMark.SearchOfClass43("@ClassID", uClass.ClassID,
+                                                                "@YearID", uYearSemester.YearID,
+                                                                "@Semester", uYearSemester.Semester,
+                                                                "@OrderLearning", intOrderLearning);
+                dtbClassSubject = objSubjectMark.GetListSubject43("@ClassID", uClass.ClassID,
+                                                                  "@YearID", uYearSemester.YearID,
+                                                                  "@Semester", uYearSemester.Semester,
+                                                                  "@NotListSpecialType", strListGraduationSpecialType);
+            }
+            else
+            {
+                if (chkViewOnlyExam1.Checked)
+                    dtbSubjectMark = objSubjectMark.SearchFirst("@ClassID", uClass.ClassID);
+                else
+                    dtbSubjectMark = objSubjectMark.SearchFinal("@ClassID", uClass.ClassID);
+                dtbClassSubject = objClassSubject.SearchSimpleList("@ClassID", uClass.ClassID,
+                                                                   "@YearID", uYearSemester.YearID,
+                                                                   "@Semester", uYearSemester.Semester,
+                                                                   "@NotListSpecialType", strListGraduationSpecialType);
+            }
+            dtbData = objStudent.GetDataTable("SIM_Student_SearchForSummary",
+                                             "@ClassID", uClass.ClassID,
+                                             "@YearID", uYearSemester.YearID,
+                                             "@Semester", uYearSemester.Semester);
+            if (dtbData != null && dtbClassSubject != null && dtbSubjectMark != null)
+            {
+                dtbClassSubject.Columns.Add("SubjectIndex", typeof(int));
+                RepairData();
+                FillData();
+                ExportToHTML();
+            }
+            else
+            {
+                MsgBox.ShowError("Việc lấy thông tin điểm bị lỗi!");
+            }
+        }
+        private bool IsValidData(bool isShowMsg)
+        {
+            if (uYearSemester.YearID == null)
+            {
+                if (isShowMsg)
+                    MsgBox.ShowWarning("Bạn phải chọn năm học!");
+                return false;
+            }
+            if (uClass.ClassID == null)
+            {
+                if (isShowMsg)
+                    MsgBox.ShowWarning("Bạn phải chọn lớp học!");
+                return false;
+            }
+            return true;
+        }
+        private bool IsRegulation43OfClass()
+        {
+            return intRegulationIDCurrent == 43 || intRegulationIDCurrent == 44 || intRegulationIDCurrent == 99;
+        }
+        private void RepairData()
+        {
+            dtbData.Columns.Add("SummaryLearningMark", typeof(double));
+            dtbData.Columns.Add("LearningLevel", typeof(string));
+            dtbData.Columns.Add("SomeDebt", typeof(int));
+            dtbData.Columns.Add("SomeCredidDebt", typeof(double));
+            dtbData.Columns.Add("DebtRatio", typeof(double));
+            dtbData.Columns.Add("EthicMark", typeof(string));
+            dtbData.Columns.Add("EthicLevel", typeof(string));
+            bolHaveNormalSubject = false;
+            for (int i = 0; i < dtbClassSubject.Rows.Count; i++)
+            {
+                DataRow drw = dtbClassSubject.Rows[i];
+                drw["SubjectIndex"] = i + 1;
+                int intSpecialType = Convert.ToInt32(drw["SpecialType"]);
+                if (intSpecialType == Global.SubjectSpecialType.BinhThuong)
+                    bolHaveNormalSubject = true;
+                AddColumnIfNotExists(dtbData, "TestAverage_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "Exam1_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "Summary1_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "Exam2_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "Summary2_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "Exam3_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "Summary3_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "FinalExam_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "FinalSummary_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "OrderLearning_" + (i + 1).ToString(), typeof(double));
+                AddColumnIfNotExists(dtbData, "LearningLevel_" + (i + 1).ToString(), typeof(string));
+                AddColumnIfNotExists(dtbData, "OtherFinalSummary_" + (i + 1).ToString(), typeof(double));
+            }
+        }
+        private void AddColumnIfNotExists(DataTable dtb, string columnName, Type dataType)
+        {
+            if (!dtb.Columns.Contains(columnName))
+                dtb.Columns.Add(columnName, dataType);
+        }
+        private void FillData()
+        {
+            DataTable dtbEthicMark = new SIM_SummaryEthicMark().Search("@YearID", uYearSemester.YearID, "@ClassID", uClass.ClassID);
+            foreach (DataRow drw in dtbData.Rows)
+            {
+                double dblTotalMark = 0;
+                int intUnitTextCount = 0;
+                int intSomeDebt = 0;
+                double dblSomeCredidDebt = 0;
+                double dblDebtRatio = 0;
+                DataRow[] rows = dtbSubjectMark.Select("StudentID='" + drw["StudentID"].ToString().Replace("'", "''") + "'");
+                foreach (DataRow drw2 in rows)
+                {
+                    FillSubjectMark(drw, drw2, ref dblTotalMark, ref intUnitTextCount, ref intSomeDebt, ref dblSomeCredidDebt);
+                }
+                if (intUnitTextCount > 0)
+                {
+                    double dblSummaryLearningMark = 0;
+                    if (intRegulationIDCurrent == 25 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44)
+                        dblSummaryLearningMark = Math.Round(dblTotalMark / intUnitTextCount, 2, MidpointRounding.AwayFromZero);
+                    else
+                        dblSummaryLearningMark = Math.Round(dblTotalMark / intUnitTextCount, 1, MidpointRounding.AwayFromZero);
+                    drw["SummaryLearningMark"] = dblSummaryLearningMark;
+                    dblDebtRatio = dblSomeCredidDebt * 100 / intUnitTextCount;
+                    drw["SomeDebt"] = intSomeDebt;
+                    drw["SomeCredidDebt"] = dblSomeCredidDebt;
+                    drw["DebtRatio"] = dblDebtRatio;
+                }
+                drw["LearningLevel"] = SimsService.SIM_SubjectMarkService.ToLearningLevel(drw, intRegulationIDCurrent);
+                FillEthicMark(drw, dtbEthicMark);
+            }
+        }
+        private void FillSubjectMark(DataRow drw, DataRow drw2, ref double dblTotalMark, ref int intUnitTextCount, ref int intSomeDebt, ref double dblSomeCredidDebt)
+        {
+            string strSubjectID = drw2["SubjectID"].ToString().Replace("'", "''");
+            DataRow[] rowSubjects = dtbClassSubject.Select("SubjectID='" + strSubjectID + "'");
+            if (rowSubjects.Length <= 0)
+                return;
+            string strIndex = rowSubjects[0]["SubjectIndex"].ToString();
+            drw["OrderLearning_" + strIndex] = drw2["OrderLearning"];
+            if (Convert.ToBoolean(drw2["IsIgnore"]))
+            {
+                drw["Summary1_" + strIndex] = -1;
+                drw["Summary2_" + strIndex] = -1;
+                drw["Summary3_" + strIndex] = -1;
+                drw["FinalSummary_" + strIndex] = -1;
+                return;
+            }
+            if (intRegulationIDCurrent == 44 || intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99)
+                FillSubjectMarkTinChi(drw, drw2, strIndex, ref dblTotalMark, ref intUnitTextCount);
+            else
+                FillSubjectMarkNienChe(drw, drw2, strIndex, ref dblTotalMark, ref intUnitTextCount, ref intSomeDebt, ref dblSomeCredidDebt);
+        }
+        private void FillSubjectMarkTinChi(DataRow drw, DataRow drw2, string strIndex, ref double dblTotalMark, ref int intUnitTextCount)
+        {
+            int intSpecialType = Convert.ToInt32(drw2["SpecialType"]);
+            if (chkViewOnlyExam1.Checked)
+            {
+                drw["FinalSummary_" + strIndex] = drw2["Summary1"];
+                drw["LearningLevel_" + strIndex] = drw2["LearningLevel1"];
+                drw["OtherFinalSummary_" + strIndex] = drw2["OtherSummary1"];
+                AddSubjectSummary(drw2["OtherSummary1"], drw2["UnitText"], intSpecialType, ref dblTotalMark, ref intUnitTextCount);
+            }
+            else
+            {
+                drw["FinalSummary_" + strIndex] = drw2["FinalSummary"];
+                drw["LearningLevel_" + strIndex] = drw2["LearningLevel"];
+                drw["OtherFinalSummary_" + strIndex] = drw2["OtherFinalSummary"];
+                AddSubjectSummary(drw2["OtherFinalSummary"], drw2["UnitText"], intSpecialType, ref dblTotalMark, ref intUnitTextCount);
+            }
+        }
+        private void FillSubjectMarkNienChe(DataRow drw, DataRow drw2, string strIndex, ref double dblTotalMark, ref int intUnitTextCount, ref int intSomeDebt, ref double dblSomeCredidDebt)
+        {
+            drw["TestAverage_" + strIndex] = drw2["TestAverage"];
+            drw["Exam1_" + strIndex] = drw2["Exam1"];
+            drw["Summary1_" + strIndex] = drw2["Summary1"];
+            if (chkViewOnlyExam1.Checked)
+            {
+                drw["FinalSummary_" + strIndex] = drw2["Summary1"];
+                if (drw["FinalSummary_" + strIndex].ToString() != "" && Convert.ToDecimal(drw["FinalSummary_" + strIndex]) < 5)
+                {
+                    intSomeDebt += 1;
+                    dblSomeCredidDebt += Convert.ToInt32(drw2["UnitText"]);
+                }
+            }
+            else
+            {
+                drw["Exam2_" + strIndex] = drw2["Exam2"];
+                drw["Summary2_" + strIndex] = drw2["Summary2"];
+                drw["Exam3_" + strIndex] = drw2["Exam3"];
+                drw["Summary3_" + strIndex] = drw2["Summary3"];
+                drw["FinalExam_" + strIndex] = drw2["FinalExam"];
+                drw["FinalSummary_" + strIndex] = drw2["FinalSummary"];
+                if (drw2["Passed"].ToString() == "0")
+                {
+                    intSomeDebt += 1;
+                    dblSomeCredidDebt += Convert.ToInt32(drw2["UnitText"]);
+                }
+            }
+            int intSpecialType = Convert.ToInt32(drw2["SpecialType"]);
+            AddSubjectSummary(drw["FinalSummary_" + strIndex], drw2["UnitText"], intSpecialType, ref dblTotalMark, ref intUnitTextCount);
+        }
+        private void AddSubjectSummary(object summaryValue, object unitTextValue, int intSpecialType, ref double dblTotalMark, ref int intUnitTextCount)
+        {
+            bool bolUseSubject = (bolHaveNormalSubject && intSpecialType == Global.SubjectSpecialType.BinhThuong)
+                                 || (bolHaveNormalSubject && intSpecialType == 6)
+                                 || (!bolHaveNormalSubject && intSpecialType == Global.SubjectSpecialType.VanHoa);
+            if (bolUseSubject && summaryValue != null && summaryValue.ToString() != "")
+            {
+                int intUnitText = Convert.ToInt32(unitTextValue);
+                dblTotalMark += Convert.ToDouble(summaryValue) * intUnitText;
+                intUnitTextCount += intUnitText;
+            }
+        }
+        private void FillEthicMark(DataRow drw, DataTable dtbEthicMark)
+        {
+            if (dtbEthicMark == null)
+                return;
+            DataRow[] rows = dtbEthicMark.Select("StudentID='" + drw["StudentID"].ToString().Replace("'", "''") + "'");
+            if (rows.Length <= 0)
+                return;
+            if (uYearSemester.Semester != null)
+            {
+                drw["EthicMark"] = rows[0]["EthicMark" + uYearSemester.Semester.ToString()];
+                drw["EthicLevel"] = rows[0]["EthicLevel" + uYearSemester.Semester.ToString()];
+            }
+            else
+            {
+                drw["EthicMark"] = rows[0]["EthicMark"];
+                drw["EthicLevel"] = rows[0]["EthicLevel"];
+            }
+        }
+        private bool IsVisibleColumn(string fieldName)
+        {
+            if (fieldName.IndexOf("Ethic", StringComparison.OrdinalIgnoreCase) >= 0)
+                return chkShowEthic.Checked;
+            if (fieldName.IndexOf("TestAverage_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return chkShowTestAverage.Checked;
+            if (fieldName.IndexOf("Exam1_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return chkShowExam1.Checked;
+            if (fieldName.IndexOf("Exam2_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return !chkViewOnlyExam1.Checked && chkShowExam2.Checked && !IsHiddenByRegulation(fieldName);
+            if (fieldName.IndexOf("Exam3_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return !chkViewOnlyExam1.Checked && chkShowExam3.Checked && !IsHiddenByRegulation(fieldName);
+            if (fieldName.IndexOf("FinalExam_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return !chkViewOnlyExam1.Checked && chkShowExam.Checked;
+            if (fieldName.IndexOf("Summary1_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return chkShowSummary1.Checked;
+            if (fieldName.IndexOf("Summary2_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return !chkViewOnlyExam1.Checked && chkShowSummary2.Checked && !IsHiddenByRegulation(fieldName);
+            if (fieldName.IndexOf("Summary3_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return !chkViewOnlyExam1.Checked && chkShowSummary3.Checked && !IsHiddenByRegulation(fieldName);
+            if (fieldName.IndexOf("FinalSummary_", StringComparison.OrdinalIgnoreCase) >= 0)
+                return !chkViewOnlyExam1.Checked && chkShowSummary.Checked;
+            return true;
+        }
+        private bool IsHiddenByRegulation(string fieldName)
+        {
+            switch (intRegulationIDCurrent)
+            {
+                case 14:
+                    return fieldName.IndexOf("Summary3_", StringComparison.OrdinalIgnoreCase) >= 0 || fieldName.IndexOf("Exam3_", StringComparison.OrdinalIgnoreCase) >= 0 || fieldName.IndexOf("TestAverage_", StringComparison.OrdinalIgnoreCase) >= 0;
+                case 4:
+                case 9:
+                case 25:
+                case 28:
+                case 40:
+                case 46:
+                    return fieldName.IndexOf("Summary2_", StringComparison.OrdinalIgnoreCase) >= 0 || fieldName.IndexOf("Exam3_", StringComparison.OrdinalIgnoreCase) >= 0;
+                case 43:
+                case 44:
+                case 99:
+                    return fieldName.IndexOf("Exam3_", StringComparison.OrdinalIgnoreCase) >= 0;
+            }
+            return false;
+        }
+        private string MarkToString(object mark)
+        {
+            if (mark == null || mark == DBNull.Value || mark.ToString() == "")
+                return "";
+            if (mark.ToString() == "-1")
+                return "M";
+            decimal decValue = Convert.ToDecimal(mark);
+            if (decValue == 100)
+                return "K.đạt";
+            if (decValue == 110)
+                return "Đạt";
+            return decValue.ToString("#,##0.0");
+        }
+        private string HtmlEncode(object value)
+        {
+            if (value == null || value == DBNull.Value)
+                return "";
+            return HttpUtility.HtmlEncode(value.ToString());
+        }
+        private string GetMarkCss(DataRow drw, string fieldName, object value)
+        {
+            string strCss = "";
+            if ((fieldName.IndexOf("FinalSummary_", StringComparison.OrdinalIgnoreCase) >= 0 && fieldName.IndexOf("OtherFinalSummary_", StringComparison.OrdinalIgnoreCase) < 0) || (chkViewOnlyExam1.Checked && fieldName.IndexOf("Summary1_", StringComparison.OrdinalIgnoreCase) >= 0))
+            {
+                if (value != null && value != DBNull.Value && value.ToString() != "" && value.ToString() != "-1" && Convert.ToDouble(value) < 5)
+                    strCss += " mark-failed";
+                string strOrderFieldName = fieldName.Replace("FinalSummary_", "OrderLearning_").Replace("Summary1_", "OrderLearning_");
+                if (dtbData.Columns.Contains(strOrderFieldName) && drw[strOrderFieldName] != DBNull.Value && drw[strOrderFieldName].ToString() != "")
+                {
+                    int intOrderLearning = Convert.ToInt32(drw[strOrderFieldName]);
+                    if (intOrderLearning == 2)
+                        strCss += " mark-relearn-2";
+                    else if (intOrderLearning > 2)
+                        strCss += " mark-relearn-3";
+                }
+            }
+            return strCss;
+        }
+        private void ExportToHTML()
+        {
